local root=assert(os.getenv('QCOM_VP_PROBE_ROOT'))..'/'
platform={moduletype='Container',qemu_inst_mgr={moduletype='QemuInstanceManager'},
    apss_instance={moduletype='QemuInstance',args={'&qemu_inst_mgr','AARCH64'},accel='tcg',
        sync_policy='multithread-quantum',qemu_args='-d in_asm,int -D '..root..'producer.log'},
    apss_router={moduletype='router'},
    apss_access={moduletype='AccessMonitor',
        initiator_socket={bind='&protection_port.target_socket'}},
    apss={moduletype='cpu_arm_cortexA53',args={'&apss_instance'},rvbar=0x300000,
        has_el3=true,has_el2=true,mem={bind='&apss_access.target_socket'}},
    protection_port={moduletype='qcom,tme-protection-port-v1',
        args={'&protection','&apss'},qad=0,
        protected_base=0x14800000,protected_size=0x10000,
        initiator_socket={bind='&ordinary_port.target_socket'}},
    ordinary_port={moduletype='qcom,tme-protection-port-v1',
        args={'&protection','&apss'},qad=2,
        protected_base=0x15800000,protected_size=0x10000,
        initiator_socket={bind='&apss_router.target_socket'}},
    ram={moduletype='gs_memory',
        target_socket={address=0x14800000,size=0x10000,bind='&apss_router.initiator_socket'}},
    ordinary_ram={moduletype='gs_memory',
        target_socket={address=0x15800000,size=0x10000,bind='&apss_router.initiator_socket'}},
    rom={moduletype='gs_memory',read_only=true,
        target_socket={address=0x300000,size=0x1000,bind='&apss_router.initiator_socket'},
        load={{bin_file=root..'producer.bin',offset=0}}},
    protection={moduletype='qcom,sm8850-tme-protection',region_count=2,
        address_bits=32,alignment_bits=12,aperture_size=0x4000,mode_reset=0,qad_count=11,
        config_owner_mask=2,apss_config_owner_mask=0xc0000001,config_secure_unspecified=false,
        target_socket={address=0x05f00000,size=0x2000,bind='&apss_router.initiator_socket'},
        apss_config_socket={address=0x01f00000,size=0x2000,bind='&apss_router.initiator_socket'}},
    undeclared={moduletype='qcom,sm8850-tme-protection',region_count=2,
        address_bits=32,alignment_bits=12,mode_reset=0,qad_count=11,
        config_owner_mask=0,config_secure_unspecified=false,
        target_socket={address=0x06f00000,size=0x2000,bind='&apss_router.initiator_socket'}}}
